    for (i = 0; i < PORT_EDGE.length; i++) {
      var e = PORT_EDGE[i];
      var pa = EDGE_V[e][0], pb = EDGE_V[e][1];
      var mx = Math.round((VERT_XY[pa][0] + VERT_XY[pb][0]) / 2 + 380);
      var my = Math.round((VERT_XY[pa][1] + VERT_XY[pb][1]) / 2 + 260);
      var dx = 380 - mx, dy = 260 - my, distance = Math.sqrt(dx * dx + dy * dy);
      mx += Math.round(dx / distance * 14);
      my += Math.round(dy / distance * 14);
      var ptxt = PORT_KIND[i] === 0 ? "3:1" : "2:1 " + RES_NAMES[PORT_KIND[i] - 1].slice(0, 1).toUpperCase();
      pieces.push({ id: "port_" + i, type: "port", board: "vertices", position: { x: mx, y: my }, text: ptxt, actions: [] });
    }
    // labels
    var turnText = m.status === "over" || s.over ? t("finished") : t("turn_player", { n: (s.seat || 0) + 1 });
    labels.push({ id: "title", text: t("title"), x: 20, y: 14, font_size: 28 });
    labels.push({ id: "turn", text: turnText, x: 20, y: 50, font_size: 20 });
    labels.push({ id: "phase", text: t("phase_" + (s.ph || "setup")), x: 300, y: 50, font_size: 20 });
    var diceText = s.dice && (s.dice[0] || s.dice[1]) ? t("dice", { a: s.dice[0], b: s.dice[1] }) : t("dice_none");
    labels.push({ id: "dice", text: diceText, x: 560, y: 50, font_size: 20 });
    var vpText = s.vp ? s.vp.map(function (v, idx) { return "P" + (idx + 1) + ": " + v; }).join("  ") : "";
    labels.push({ id: "scores", text: t("scores", { v: vpText }), x: 20, y: 600, font_size: 20 });
    if (s.winVp) labels.push({ id: "target", text: t("target", { v: s.winVp }), x: 560, y: 600, font_size: 20 });
    if (s.myHand) labels.push({ id: "hand", text: t("hand", { wood: s.myHand[0], sheep: s.myHand[1], wheat: s.myHand[2], brick: s.myHand[3], ore: s.myHand[4] }), x: 20, y: 632, font_size: 18 });
    if (s.myDev) {
      var devTotal = 0; for (i = 0; i < 5; i++) devTotal += s.myDev[i] + (s.myNewDev ? s.myNewDev[i] : 0);
      labels.push({ id: "devcards", text: t("devcards", { n: devTotal, knight: s.myDev[0], vp: s.myDev[1], road: s.myDev[2], plenty: s.myDev[3], monopoly: s.myDev[4] }), x: 20, y: 664, font_size: 18 });
    }
    if (s.trade) {
      labels.push({ id: "trade", text: t("trade_offer", { from: s.trade.from + 1, to: s.trade.to + 1 }), x: 20, y: 696, font_size: 18 });
      labels.push({ id: "trade_give", text: t("give", { wood: s.trade.give[0], sheep: s.trade.give[1], wheat: s.trade.give[2], brick: s.trade.give[3], ore: s.trade.give[4] }), x: 20, y: 724, font_size: 18 });
      labels.push({ id: "trade_want", text: t("want", { wood: s.trade.want[0], sheep: s.trade.want[1], wheat: s.trade.want[2], brick: s.trade.want[3], ore: s.trade.want[4] }), x: 20, y: 752, font_size: 18 });
    }
    if (s.ph === "target") labels.push({ id: "hint", text: t("choose_target"), x: 20, y: 696, font_size: 18 });
    if (local.mode === "knight" || local.mode === "robber") labels.push({ id: "hint", text: t("choose_hex"), x: 20, y: 696, font_size: 18 });
    if (local.mode === "road") labels.push({ id: "hint", text: t("choose_edges"), x: 20, y: 696, font_size: 18 });
    if (local.selHex !== undefined && local.selHex !== null) labels.push({ id: "hint2", text: t("choose_victim"), x: 20, y: 724, font_size: 18 });
    function addVertexTargets(moves, prefix) {
      moves.forEach(function (mv) { targets.push({ id: prefix + mv.vertex, board: "vertices", position: { cell: String(mv.vertex) } }); });
    }
    function addEdgeTargets(moves, prefix) {
      moves.forEach(function (mv) {
        var e = mv.edge !== undefined ? mv.edge : mv.edge1;
        var a = EDGE_V[e][0], b = EDGE_V[e][1];
        targets.push({ id: prefix + e, board: "vertices", position: { x: Math.round((VERT_XY[a][0] + VERT_XY[b][0]) / 2 + 380), y: Math.round((VERT_XY[a][1] + VERT_XY[b][1]) / 2 + 260) } });
      });
    }
    if (s.ph === "setup") {
      if (s.setupSub === "settlement") addVertexTargets(legalOf("placeSettlement"), "v_");
      else addEdgeTargets(legalOf("placeRoad"), "e_");
    } else if (s.ph === "action") {
      addVertexTargets(legalOf("buildSettlement"), "v_");
      addVertexTargets(legalOf("buildCity"), "v_");
      if (!local.mode) addEdgeTargets(legalOf("buildRoad"), "e_");
      if (local.mode === "road") {
        // road building edges: first tap picks edge1, second tap picks edge2
        var seen = {};
        var rbMoves = legalOf("playRoadBuilding");
        var edgeList = [];
        if (local.selEdge1 === null || local.selEdge1 === undefined) {
          rbMoves.forEach(function (mv) { if (!seen[mv.edge1]) { seen[mv.edge1] = true; edgeList.push(mv.edge1); } });
        } else {
          rbMoves.forEach(function (mv) { if (mv.edge1 === local.selEdge1 && !seen[mv.edge2]) { seen[mv.edge2] = true; edgeList.push(mv.edge2); } });
        }
        edgeList.forEach(function (ee) { targets.push({ id: "rb_" + ee, board: "vertices", position: { x: Math.round((VERT_XY[EDGE_V[ee][0]][0] + VERT_XY[EDGE_V[ee][1]][0]) / 2 + 380), y: Math.round((VERT_XY[EDGE_V[ee][0]][1] + VERT_XY[EDGE_V[ee][1]][1]) / 2 + 260) } }); });
      }
    }
    if ((s.ph === "robber" || local.mode === "knight") && (local.selHex === undefined || local.selHex === null)) {
      var hexMoves = s.ph === "robber" ? legalOf("moveRobber") : legalOf("playKnight");
      var seenHex = {};
      hexMoves.forEach(function (mv) { if (!seenHex[mv.hex]) { seenHex[mv.hex] = true; targets.push({ id: "h_" + mv.hex, board: "island", position: { cell: String(mv.hex) } }); } });
    }
    // controls
    var y = 800;
    function btn(id, label, disabled) { controls.push({ id: id, kind: "button", label: label, disabled: !!disabled }); }
    function choice(id, label, opts, val) { controls.push({ id: id, kind: "choice", label: label, value: val === undefined ? opts[0].value : val, options: opts }); }
    var resOpts = RES_NAMES.map(function (r, idx) { return { value: String(idx), label: t(r) }; });
    if (active && s.ph === "target") {
      var targetOpts = [];
      for (i = 3; i <= 15; i++) targetOpts.push({ value: String(i), label: String(i) });
      choice("targetVp", t("target", { v: local.targetVp === undefined ? 10 : local.targetVp }), targetOpts, local.targetVp === undefined ? "10" : String(local.targetVp));
      btn("start", t("start"));
    }
    if (active && s.ph === "roll") btn("roll", t("roll"));
    if (active && s.ph === "action") {
      btn("endTurn", t("end_turn"));
      if (legalOf("buyDev").length) btn("buyDev", t("buy_dev"));
      if (legalOf("playKnight").length) btn("knight", t("play_knight"));
      if (legalOf("playRoadBuilding").length) btn("road", t("play_road_building"));
      if (legalOf("playYearOfPlenty").length) {
        choice("plenty1", t("plenty_card"), resOpts, local.plenty1 === undefined ? "0" : local.plenty1);
        choice("plenty2", t("plenty_card"), resOpts, local.plenty2 === undefined ? "0" : local.plenty2);
        btn("plenty", t("play_year"));
      }
      if (legalOf("playMonopoly").length) {
        choice("monoRes", t("monopoly_card"), resOpts, local.monoRes === undefined ? "0" : local.monoRes);
        btn("monopoly", t("play_monopoly"));
      }
      choice("bankGive", t("give"), resOpts, local.bankGive === undefined ? defBankG : local.bankGive);
      choice("bankWant", t("want"), resOpts, local.bankWant === undefined ? defBankW : local.bankWant);
      var bankG = parseInt(local.bankGive === undefined ? defBankG : local.bankGive, 10), bankW = parseInt(local.bankWant === undefined ? defBankW : local.bankWant, 10);
      var bankOk = s.myHand && bankG !== bankW && s.myHand[bankG] >= portRateFor(s, mySeat, bankG);
      btn("bankTrade", t("bank_trade"), !bankOk);
      // player trade
      var playerOpts = [];
      for (i = 0; i < (s.vp ? s.vp.length : 0); i++) if (i !== mySeat) playerOpts.push({ value: String(i), label: "P" + (i + 1) });
      if (playerOpts.length) {
        choice("tradeTo", t("offer_trade"), playerOpts, local.tradeTo === undefined ? playerOpts[0].value : local.tradeTo);
        choice("tradeGiveRes", t("give"), resOpts, local.tradeGiveRes === undefined ? "0" : local.tradeGiveRes);
        choice("tradeWantRes", t("want"), resOpts, local.tradeWantRes === undefined ? "1" : local.tradeWantRes);
        var trG = parseInt(local.tradeGiveRes || "0", 10), trW = parseInt(local.tradeWantRes || "1", 10);
        var tradeOk = s.myHand && trG !== trW && s.myHand[trG] >= 1;
        btn("offerTrade", t("offer_trade"), !tradeOk);
      }
      if (local.mode) btn("cancel", t("cancel"));
    }
    if (active && s.ph === "trade") { btn("accept", t("accept")); btn("decline", t("decline")); }
    if (active && s.ph === "discard") {
      for (i = 0; i < 5; i++) controls.push({ id: "disc_" + i, kind: "number", label: t(RES_NAMES[i]), value: local.discard ? local.discard[i] : 0, min: 0, max: s.myHand ? s.myHand[i] : 0, step: 1 });
      var discSum = 0; if (local.discard) for (i = 0; i < 5; i++) discSum += local.discard[i] || 0;
      btn("discard", t("discard"), discSum !== s.discardNeed);
    }
    if (local.selHex !== undefined && local.selHex !== null) {
      // victim buttons for the selected hex
      var victims = [];
      var seenV = {};
      legal.filter(function (mv) { return (mv.type === "moveRobber" || mv.type === "playKnight") && mv.hex === local.selHex; }).forEach(function (mv) { if (mv.victim >= 0 && !seenV[mv.victim]) { seenV[mv.victim] = true; victims.push(mv.victim); } });
      victims.forEach(function (v) { btn("victim_" + v, t("victim", { n: v + 1 })); });
      var hasNone = legal.some(function (mv) { return (mv.type === "moveRobber" || mv.type === "playKnight") && mv.hex === local.selHex && mv.victim === -1; });
      if (hasNone) btn("victim_none", t("victim_none"));
    }
    var out = { scene: { pieces: pieces, targets: targets, labels: labels, controls: controls, paths: paths }, local_state: local };
    if (makeMove) out.make_move = makeMove;
    return out;
  },
  // Paths for the last accepted move, rebuilt purely from the filtered
  // view (works after a reload; local_state is never consulted). The
  // robber is the single stable piece "robber" on the island board;
  // settlements are the stable per-vertex pieces "b_<vertex>" on the
  // vertices board. Roads are scene paths, not pieces, and cities reuse
  // the settlement's piece, so neither gets a path here.
  getLastMoveAnimations: function (view, scene) {
    if (!view || !Object.prototype.hasOwnProperty.call(view, "last_move")) return null;
    var move = view.last_move;
    if (!move || (move.kind !== "robber" && move.kind !== "build")) return [];
    if (!move.from) return [];
    var wantId = move.kind === "robber" ? "robber" : move.piece_id;
    if (!wantId) return [];
    var pieces = (scene && scene.pieces) || [];
    var piece = null;
    for (var i = 0; i < pieces.length; i++) if (pieces[i].id === wantId) piece = pieces[i];
    if (!piece) return [];
    var dest = { board: piece.board, position: piece.position };
    return [{ piece_id: wantId, duration_ms: move.kind === "robber" ? 900 : 600, path: [move.from, dest] }];
  }
};
